package com.leotv.detail;
import android.app.Activity;import android.content.Intent;import android.os.SystemClock;import android.view.*;
import org.json.JSONObject;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
import java.util.concurrent.TimeUnit;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=23,manifest=Config.NONE) @LooperMode(LooperMode.Mode.PAUSED)
public class PosterSearchTest {
 Activity activity;
 @Before public void open(){activity=Robolectric.buildActivity(Activity.class).setup().get();}
 JSONObject item(String name)throws Exception{return new JSONObject().put("vod_id","fictional-id").put("vod_name",name).put("indexs",0).put("changeable",0);}
 @Test public void longPressOpensNativeGlobalSearchAndDoesNotUseTheResourceClick()throws Exception{View poster=new View(activity);final int[] clicks={0};poster.setOnClickListener(v->clicks[0]++);PosterSearch.attach(activity,poster,item("虚构剧集 第一季"));assertTrue(poster.performLongClick());Intent next=Shadows.shadowOf(activity).getNextStartedActivity();assertEquals("com.fongmi.android.tv.ui.activity.CollectActivity",next.getComponent().getClassName());assertEquals("虚构剧集 第一季",next.getStringExtra("keyword"));assertEquals(0,clicks[0]);assertNull(Shadows.shadowOf(activity).getNextStartedActivity());}
 @Test public void nativeTaskFlagsAndWholeKeywordArePreservedForBothClients(){for(boolean mobile:new boolean[]{false,true}){Intent next=PosterSearch.intent(activity,"虚构剧集 S02 (2026)",mobile);assertEquals("com.fongmi.android.tv.ui.activity."+(mobile?"SearchActivity":"CollectActivity"),next.getComponent().getClassName());assertEquals("虚构剧集 S02 (2026)",next.getStringExtra("keyword"));assertEquals(mobile?0:Intent.FLAG_ACTIVITY_NEW_TASK,next.getFlags()&Intent.FLAG_ACTIVITY_NEW_TASK);}}
 @Test public void reboundOrCarouselPostersUseTheCurrentItem()throws Exception{View poster=new View(activity);final JSONObject[] current={item("虚构甲")};PosterSearch.attach(activity,poster,()->current[0]);current[0]=item("虚构乙");assertTrue(poster.performLongClick());assertEquals("虚构乙",Shadows.shadowOf(activity).getNextStartedActivity().getStringExtra("keyword"));PosterSearch.attach(activity,poster,item("虚构丙"));assertTrue(poster.performLongClick());assertEquals("虚构丙",Shadows.shadowOf(activity).getNextStartedActivity().getStringExtra("keyword"));}
 @Test public void unboundPostersReleaseTheOldResourceAction()throws Exception{View poster=new View(activity);PosterSearch.attach(activity,poster,item("虚构旧条目"));PosterSearch.detach(poster);assertFalse(poster.performLongClick());assertNull(Shadows.shadowOf(activity).getNextStartedActivity());}
 @Test public void foldersActionsAndEmptyItemsKeepTheNativeExclusions()throws Exception{assertEquals("",PosterSearch.keyword(item("虚构目录").put("vod_tag","folder")));assertEquals("",PosterSearch.keyword(item("虚构操作").put("vod_id","action:fictional")));assertFalse(PosterSearch.open(activity,null));assertFalse(PosterSearch.open(activity,item("  ")));assertNull(Shadows.shadowOf(activity).getNextStartedActivity());}
 @Test public void phoneCarouselGestureLongPressIsConsumedBeforeFingerUp()throws Exception{PosterGestureSubject page=new PosterGestureSubject(activity);activity.setContentView(page.heroFrame);page.heroFrame.measure(View.MeasureSpec.makeMeasureSpec(400,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(600,View.MeasureSpec.EXACTLY));page.heroFrame.layout(0,0,400,600);final int[] clicks={0};page.heroFrame.setOnClickListener(v->clicks[0]++);PosterSearch.attach(activity,page.heroFrame,item("虚构轮播"));page.heroGestures();long down=SystemClock.uptimeMillis();MotionEvent event=MotionEvent.obtain(down,down,MotionEvent.ACTION_DOWN,100,100,0);page.heroFrame.dispatchTouchEvent(event);event.recycle();Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(1000,TimeUnit.MILLISECONDS);Intent next=Shadows.shadowOf(activity).getNextStartedActivity();assertNotNull("The production phone gesture must recognize a held poster",next);assertEquals("虚构轮播",next.getStringExtra("keyword"));event=MotionEvent.obtain(down,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,100,100,0);page.heroFrame.dispatchTouchEvent(event);event.recycle();assertEquals("Finger-up after long press must not open detail/playback",0,clicks[0]);assertNull(Shadows.shadowOf(activity).getNextStartedActivity());}
}
